using Neemle.CSharpComposer.Model;
using Neemle.CSharpComposer.Rendering;
using static Neemle.CSharpComposer.Tests.Scenarios.Build;

namespace Neemle.CSharpComposer.Tests.Scenarios;

// GENE-29 F2 (AD 84939297 v2 C2-C4): the formatting policy of the fresh renderer. A row renders a built document or a
// parsed one detached from its source (so the formatter writes all of it): line breaking at RenderOptions.MaxLineLength,
// comments in breakable lists, the blank-line table, directive indentation, `else if` chains, block lambdas, opaque
// text, RenderOptions.Newline and the final line break. Each row failed on 4647666 or covers a new branch.
public static class FormatterScenarios
{
    // The source parsed and detached: rendered by the formatter alone.
    static CsDocument Fresh(string source) => (CsDocument)Src(source).Detach();

    static string Fresh(string source, RenderOptions options) => Fresh(source).Render(options);

    static CsComment Line(string text, CommentPlacement placement = CommentPlacement.Leading) => new("// " + text, CommentKind.Line, placement);

    static CsComment Block(string text, CommentPlacement placement = CommentPlacement.Leading) => new("/* " + text + " */", CommentKind.Block, placement);

    static CsExpression Call(string name, params CsExpression[] arguments) => Cs.Call(Cs.Id(name), arguments);

    static CsExpression[] Ids(string prefix, int count) => Enumerable.Range(1, count).Select(i => Cs.Id(prefix + i)).ToArray();

    static CsDocument Statements(params CsStatement[] statements) => InMethod(statements);

    const string Long = "argumentNumberOne, argumentNumberTwo, argumentNumberThree, argumentNumberFour, argumentNumberFive, argumentNumberSix";

    // The last enum member of `source` moved to the start of the list, after `change` (a parsed document: the
    // preserved path splices the members' source text).
    static CsDocument MoveLast(string source, Func<CsDocument, NodePath, CsDocument>? change = null)
    {
        var document = Src(source);
        var last = document.Descendants().Last(n => n.Node is CsEnumMember).Path;
        if (change != null) document = change(document, last);
        var path = document.Descendants().Last(n => n.Node is CsEnumMember).Path;
        var type = document.Descendants().First(n => n.Node is CsTypeDeclaration).Path;
        return document.Move(path, type, 0);
    }

    public static IEnumerable<Scenario> All()
    {
