        yield return new("gene29.f2.width.arguments", () => Fresh("class C { void M() { Run(" + Long + "); Run(a, b); } }"), "class C\n{\n    void M()\n    {\n        Run(\n            argumentNumberOne,\n            argumentNumberTwo,\n            argumentNumberThree,\n            argumentNumberFour,\n            argumentNumberFive,\n            argumentNumberSix);\n        Run(a, b);\n    }\n}\n");
