        yield return new("gene29.f2.width.nested-refit", () => Fresh("class C { void M() { Run(Inner(" + Long + "), Other(a, b), Third(first, second, third, fourth, fifth, sixth, seventh)); } }"), "class C\n{\n    void M()\n    {\n        Run(\n            Inner(\n                argumentNumberOne,\n                argumentNumberTwo,\n                argumentNumberThree,\n                argumentNumberFour,\n                argumentNumberFive,\n                argumentNumberSix),\n            Other(a, b),\n            Third(first, second, third, fourth, fifth, sixth, seventh));\n    }\n}\n");
